// specs/quran/spec.md — Quran Ayat core domain. Pure TypeScript; the corpus is
// injected, so there is no I/O and no vendor type here.

export interface QuranSura {
  n: number
  ayahs: number
  ar: string
  latin: string
  ms: string
  en: string
}

export interface QuranJuz {
  juz: number
  surah: number
  ayah: number
  /** Global ayah index of the juz's first ayah (0-based). */
  start: number
  count: number
}

export interface QuranIndex {
  total: number
  suras: QuranSura[]
  juzs: QuranJuz[]
}

export interface Ref {
  surah: number
  ayah: number
}

export interface AyahRef extends Ref {
  juz: number
  /** Global ayah index (0-based). */
  index: number
}

export interface AyahRange {
  juzMin: number
  juzMax: number
  surahMin: number
  surahMax: number
}

/**
 * What the reader draws from: the whole Quran, a juz range, or one surah. A
 * scope is always exactly one of these; the juz range and the surah never
 * combine.
 */
export type Scope =
  | { kind: 'all' }
  | { kind: 'juz'; juzMin: number; juzMax: number }
  | { kind: 'surah'; surah: number }

export type RevealKind = 'juz' | 'surah' | 'ayah'

export interface Reveal {
  juz: boolean
  surah: boolean
  ayah: boolean
  /** How many following ayahs are shown. */
  next: number
}

export const QURAN_TOTAL = 6236
export const SURA_COUNT = 114
export const JUZ_COUNT = 30

/** Global index of a `(surah, ayah)` reference; -1 when out of range. */
export function indexOfAyah(index: QuranIndex, ref: Ref): number {
  const sura = index.suras[ref.surah - 1]
  if (!sura || ref.ayah < 1 || ref.ayah > sura.ayahs) return -1
  let offset = 0
  for (let i = 0; i < ref.surah - 1; i += 1) offset += index.suras[i]!.ayahs
  return offset + ref.ayah - 1
}

/** The ayah at a global index; null when out of range. */
export function ayahAt(index: QuranIndex, globalIndex: number): AyahRef | null {
  if (!Number.isInteger(globalIndex) || globalIndex < 0) return null
  if (globalIndex >= index.total) return null
  let remaining = globalIndex
  for (const sura of index.suras) {
    if (remaining < sura.ayahs) {
      return {
        surah: sura.n,
        ayah: remaining + 1,
        juz: juzOfIndex(index, globalIndex),
        index: globalIndex,
      }
    }
    remaining -= sura.ayahs
  }
  return null
}

/** The juz (1–30) an ayah at a global index belongs to. */
export function juzOfIndex(index: QuranIndex, globalIndex: number): number {
  let juz = 1
  for (const part of index.juzs) {
    if (globalIndex >= part.start) juz = part.juz
    else break
  }
  return juz
}

/** Clamp a range into the corpus and order each pair min ≤ max. */
export function normalizeRange(range: AyahRange): AyahRange {
  const clamp = (value: number, min: number, max: number) =>
    Math.min(max, Math.max(min, Math.round(Number.isFinite(value) ? value : min)))
  const juzA = clamp(range.juzMin, 1, JUZ_COUNT)
  const juzB = clamp(range.juzMax, 1, JUZ_COUNT)
  const suraA = clamp(range.surahMin, 1, SURA_COUNT)
  const suraB = clamp(range.surahMax, 1, SURA_COUNT)
  return {
    juzMin: Math.min(juzA, juzB),
    juzMax: Math.max(juzA, juzB),
    surahMin: Math.min(suraA, suraB),
    surahMax: Math.max(suraA, suraB),
  }
}

/** The intersection range a scope stands for. */
export function scopeRange(scope: Scope): AyahRange {
  if (scope.kind === 'juz') {
    const clamp = (value: number) =>
      Math.min(JUZ_COUNT, Math.max(1, Math.round(value)))
    const a = clamp(scope.juzMin)
    const b = clamp(scope.juzMax)
    return {
      juzMin: Math.min(a, b),
      juzMax: Math.max(a, b),
      surahMin: 1,
      surahMax: SURA_COUNT,
    }
  }
  if (scope.kind === 'surah') {
    const surah = Math.min(SURA_COUNT, Math.max(1, Math.round(scope.surah)))
    return { juzMin: 1, juzMax: JUZ_COUNT, surahMin: surah, surahMax: surah }
  }
  return { ...WHOLE_QURAN }
}

export const WHOLE_QURAN: AyahRange = {
  juzMin: 1,
  juzMax: JUZ_COUNT,
  surahMin: 1,
  surahMax: SURA_COUNT,
}

/** First and last global index of the filtered set; null when empty. */
export function rangeBounds(
  index: QuranIndex,
  range: AyahRange,
): { start: number; end: number } | null {
  const lastJuz = index.juzs.length
  const juzMin = Math.min(lastJuz, Math.max(1, range.juzMin))
  const juzMax = Math.min(lastJuz, Math.max(1, range.juzMax))
  const juzStart = index.juzs.find((part) => part.juz === juzMin)
  const juzEnd = index.juzs.find((part) => part.juz === juzMax)
  if (!juzStart || !juzEnd) return null
  let suraSurahFirst = 0
  let suraSurahLast = 0
  for (const sura of index.suras) {
    if (sura.n < range.surahMin) suraSurahFirst += sura.ayahs
    if (sura.n <= range.surahMax) suraSurahLast += sura.ayahs
  }
  const start = Math.max(juzStart.start, suraSurahFirst)
  const end = Math.min(juzEnd.start + juzEnd.count - 1, suraSurahLast - 1)
  return start <= end ? { start, end } : null
}

/** Number of ayahs in the filtered set. */
export function rangeCount(index: QuranIndex, range: AyahRange): number {
  const bounds = rangeBounds(index, range)
  return bounds ? bounds.end - bounds.start + 1 : 0
}

/**
 * Pick an ayah uniformly from the filtered set. `rng` returns [0, 1); a seeded
 * generator makes a pick reproducible.
 */
export function pickAyah(
  index: QuranIndex,
  range: AyahRange,
  rng: () => number = Math.random,
): AyahRef | null {
  const bounds = rangeBounds(index, range)
  if (!bounds) return null
  const span = bounds.end - bounds.start + 1
  const offset = Math.min(span - 1, Math.floor(rng() * span))
  return ayahAt(index, bounds.start + offset)
}

/** The next ayah inside the range, crossing surah boundaries; null at the end. */
export function nextAyah(
  index: QuranIndex,
  ref: Ref,
  range: AyahRange,
): AyahRef | null {
  const bounds = rangeBounds(index, range)
  if (!bounds) return null
  const current = indexOfAyah(index, ref)
  if (current < 0) return null
  const next = current + 1
  if (next < bounds.start || next > bounds.end) return null
  return ayahAt(index, next)
}

/** The refs for the passage: the ayah plus `count` following ayahs, in range. */
export function passage(
  index: QuranIndex,
  ref: Ref,
  range: AyahRange,
  count: number,
): AyahRef[] {
  const start = ayahAt(index, indexOfAyah(index, ref))
  if (!start) return []
  const result = [start]
  let cursor: AyahRef | null = start
  for (let i = 0; i < count && cursor; i += 1) {
    cursor = nextAyah(index, cursor, range)
    if (cursor) result.push(cursor)
  }
  return result
}

export function initialReveal(): Reveal {
  return { juz: false, surah: false, ayah: false, next: 0 }
}

/** Latch one reveal; already-revealed kinds are unchanged. */
export function reveal(state: Reveal, kind: RevealKind): Reveal {
  return { ...state, [kind]: true }
}

/** Add one following ayah to the passage. */
export function revealNext(state: Reveal): Reveal {
  return { ...state, next: state.next + 1 }
}

/** Show the whole reference at once. */
export function revealAll(state: Reveal): Reveal {
  return { ...state, juz: true, surah: true, ayah: true }
}

/**
 * Reveal the Arabic text of one row in the passage; already-shown rows and
 * out-of-range indices are unchanged. Index 0 is the first ayah.
 */
export function revealTextAt(
  shown: readonly boolean[],
  index: number,
): readonly boolean[] {
  if (!Number.isInteger(index) || index < 0 || index >= shown.length) return shown
  if (shown[index]) return shown
  const next = shown.slice()
  next[index] = true
  return next
}

const DIACRITICS = /[\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g

/** Lowercase, strip diacritics and punctuation, collapse spaces. */
export function normalizeName(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(DIACRITICS, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

function levenshtein(a: string, b: string): number {
  if (a === b) return 0
  if (!a.length) return b.length
  if (!b.length) return a.length
  let previous = Array.from({ length: b.length + 1 }, (_, i) => i)
  for (let i = 1; i <= a.length; i += 1) {
    const current = [i]
    for (let j = 1; j <= b.length; j += 1) {
      current[j] = Math.min(
        previous[j]! + 1,
        current[j - 1]! + 1,
        previous[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1),
      )
    }
    previous = current
  }
  return previous[b.length]!
}

function isSubsequence(query: string, name: string): boolean {
  let cursor = 0
  for (const char of name) {
    if (char === query[cursor]) cursor += 1
    if (cursor === query.length) return true
  }
  return false
}

/** Score a normalized query against one candidate name; lower is better. */
function scoreName(query: string, candidate: string): number {
  const tokens = candidate.split(' ').filter(Boolean)
  let best = Number.POSITIVE_INFINITY
  for (const token of [candidate, ...tokens]) {
    if (token === query) best = Math.min(best, 0)
    else if (token.startsWith(query)) best = Math.min(best, 1)
    else if (token.includes(query)) best = Math.min(best, 2)
    else if (query.length >= 2 && isSubsequence(query, token))
      best = Math.min(best, 3)
    else {
      const distance = levenshtein(query, token)
      const allowed = query.length >= 6 ? 2 : 1
      if (distance <= allowed) best = Math.min(best, 4 + distance)
    }
  }
  return best
}

/**
 * Rank surahs by a Latin-alphabet fuzzy query. Malay and English names weigh
 * equally; an empty query returns every surah in order.
 */
export function searchSurah(index: QuranIndex, query: string): QuranSura[] {
  const normalized = normalizeName(query)
  if (!normalized) return [...index.suras]
  const ranked: { sura: QuranSura; score: number }[] = []
  for (const sura of index.suras) {
    const score = Math.min(
      scoreName(normalized, normalizeName(sura.latin)),
      scoreName(normalized, normalizeName(sura.ms)),
      scoreName(normalized, normalizeName(sura.en)),
    )
    if (Number.isFinite(score)) ranked.push({ sura, score })
  }
  ranked.sort((a, b) => a.score - b.score || a.sura.n - b.sura.n)
  return ranked.map((entry) => entry.sura)
}

/** Validate a corpus index; returns the first problem, or null when sound. */
export function checkIndex(index: QuranIndex): string | null {
  if (index.suras.length !== SURA_COUNT) return 'expected 114 surahs'
  if (index.juzs.length !== JUZ_COUNT) return 'expected 30 juz'
  const total = index.suras.reduce((sum, sura) => sum + sura.ayahs, 0)
  if (total !== index.total) return 'surah counts do not sum to the total'
  if (total !== QURAN_TOTAL) return `expected ${QURAN_TOTAL} ayahs, got ${total}`
  let start = 0
  for (const [i, part] of index.juzs.entries()) {
    if (part.juz !== i + 1) return 'juz numbers are not contiguous'
    if (part.start !== start) return `juz ${part.juz} starts at the wrong index`
    if (part.count <= 0) return `juz ${part.juz} is empty`
    start += part.count
  }
  if (start !== total) return 'juz counts do not cover the corpus'
  return null
}
